package org.apache.commons.compress.archivers.cpio;

import java.io.*;
import java.io.ByteArrayOutputStream;
import java.io.File;
import java.io.FilterOutputStream;
import java.io.IOException;
import java.io.OutputStream;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import org.apache.commons.compress.archivers.ArchiveEntry;
import org.apache.commons.compress.archivers.ArchiveOutputStream;
import org.apache.commons.compress.archivers.cpio.CpioArchiveOutputStream;
import org.apache.commons.compress.utils.ArchiveUtils;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for CpioArchiveOutputStream.close()
 */
public class CpioArchiveOutputStream_close_TriageGen0Test {

    /**
     * Tests that close() successfully closes an open stream, 
     * calls finish(), and sets the closed flag.
     */
    @Test
    public void testClose_Success() throws IOException {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        try (CpioArchiveOutputStream cos = new CpioArchiveOutputStream(baos, CpioArchiveOutputStream.BUILD)) {
            // Verify initial state via behavior: calling close should not throw exception
            cos.close();
        }
        // If we reached here without exception, the happy path is covered.
    }

    /**
     * Tests that calling close() multiple times does not result in multiple calls 
     * to finish() or out.close() (idempotency check via the 'if (!this.closed)' branch).
     */
    @Test
    public void testClose_MultipleCalls() throws IOException {
        SpyOutputStream spyOut = new SpyOutputStream();
        CpioArchiveOutputStream cos = new CpioArchiveOutputStream(spyOut, CpioArchiveOutputStream.BUILD);

        cos.close();
        int firstCloseCount = spyOut.closeCount;

        // Second call should hit the 'if (this.closed)' branch and do nothing
        cos.close();

        Assert.assertEquals("Close should be called on underlying stream only once", 1, spyOut.closeCount);
    }

    /**
     * Tests that if the underlying stream throws an IOException during close, 
     * the exception is propagated.
     */
    @Test(expected = IOException.class)
    public void testClose_ThrowsIOException() throws IOException {
        ThrowingOutputStream throwingOut = new ThrowingOutputStream();
        CpioArchiveOutputStream cos = new CpioArchiveOutputStream(throwingOut, CpioArchiveOutputStream.BUILD);

        cos.close();
    }

    /**
     * Helper class to track how many times close was called on the underlying stream.
     */
    private static class SpyOutputStream extends ByteArrayOutputStream {
        int closeCount = 0;

        @Override
        public void close() throws IOException {
            closeCount++;
            super.close();
        }
    }

    /**
     * Helper class to force an IOException on close.
     */
    private static class ThrowingOutputStream extends OutputStream {
        @Override
        public void write(int b) throws IOException {
            // no-op
        }

        @Override
        public void close() throws IOException {
            throw new IOException("Simulated close failure");
        }
    }
}
